 "content": "from collections import Counter


def transform(grid):
    """Fill the interiors of outlined rectangular frames with color 4."""
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    colors = [c for c in counts if c != background]
    if not colors:
        return [row[:] for row in grid]
    frame = max(colors, key=lambda c: counts[c])
    out = [row[:] for row in grid]

    # A frame is a rectangle whose full perimeter is the foreground color
    # and whose interior is background. Enumerate all possible frames.
    for r1 in range(h - 2):
        for r2 in range(r1 + 2, h):
            for c1 in range(w - 2):
                for c2 in range(c1 + 2, w):
                    if not all(grid[r1][c] == frame and grid[r2][c] == frame
                               for c in range(c1, c2 + 1)):
                        continue
                    if not all(grid[r][c1] == frame and grid[r][c2] == frame
                               for r in range(r1, r2 + 1)):
                        continue
                    if not all(grid[r][c] == background
                               for r in range(r1 + 1, r2)
                               for c in range(c1 + 1, c2)):
                        continue
                    for r in range(r1 + 1, r2):
                        for c in range(c1 + 1, c2):
                            out[r][c] = 4
    return out


if __name__ == "__main__":
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
